mapper.select:
SELECT t1.corp_gr AS corpGr , TO_CHAR(t1.TR_YMD, 'YYYY-MM-DD') AS trYmd , t1.TR_CD AS trCd , t1.BALH_CO AS balhCo , t1.BAED_MTH AS baedMth , t1.BAEJ_MTH AS baejMth , t1.CASH_ILBAN_RT AS cashIlbanRt , t1.CASH_WOOS_RT AS cashWoosRt , t1.STOCK_ILBAN_RT AS stockIlbanRt , t1.STOCK_WOOS_RT AS stockWoosRt , TO_CHAR(t1.BROK_YMD, 'YYYY-MM-DD') AS brokYmd , TO_CHAR(t1.JUCHONG_YMD, 'YYYY-MM-DD') AS juchongYmd , jb.BALH_NM AS balhNm , jb.BALH_NM AS xxBalhCo , CASE WHEN t1.stock_woos_rt = 0 THEN NULL ELSE t1.stock_woos_rt * 100 END AS stockWoosPer , CASE WHEN t1.stock_ilban_rt = 0 THEN NULL ELSE t1.stock_ilban_rt * 100 END AS stockIlbanPer , CASE WHEN t1.cash_woos_rt = 0 THEN NULL ELSE t1.cash_woos_rt * 100 END AS cashWoosPer , CASE WHEN t1.cash_ilban_rt = 0 THEN NULL ELSE t1.cash_ilban_rt * 100 END AS cashIlbanPer , t1.ILBAN_AEK AS ilbanAek , t1.WOOS_AEK AS woosAek , CASE WHEN t1.tr_ymd >= TO_DATE(REPLACE(#{workDate}, '-', ''), 'YYYYMMDD') THEN 1 ELSE 0 END AS pVisible FROM SJT0BK t1 LEFT OUTER JOIN SJX0JB jb ON jb.BALH_CO = t1.BALH_CO WHERE 1=1
AND t1.corp_gr = #{corpGr}
AND t1.TR_YMD = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD') AND t1.TR_CD = #{trCd} ORDER BY t1.balh_co ASC

SELECT t1.corp_gr AS corpGr , TO_CHAR(t1.TR_YMD, 'YYYY-MM-DD') AS trYmd , t1.TR_CD AS trCd , t1.BALH_CO AS balhCo , t1.JM_CD AS jjCd , t1.JM_CD AS jmCd , t1.CASH_RT AS cashRt , t1.STOCK_RT AS stockRt , t1.BAED_AEK AS baedAek , t1.cash_rt * 100 AS cashPer , t1.stock_rt * 100 AS stockPer , f_jm_nm(t1.corp_gr, t1.jm_cd) AS xxJjCd , f_jm_nm(t1.corp_gr, t1.jm_cd) AS jmNm , CASE WHEN t1.tr_ymd >= TO_DATE(REPLACE(#{workDate}, '-', ''), 'YYYYMMDD') THEN 1 ELSE 0 END AS pVisible FROM sjt0bj t1 WHERE 1=1
AND t1.corp_gr = #{corpGr}
AND t1.TR_YMD = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD') AND t1.TR_CD = #{trCd} AND t1.BALH_CO = #{balhCo} ORDER BY t1.jm_cd ASC

SELECT aekm
  FROM SJX0JB
 WHERE balh_co = #{balhCo}

mapper.update:
UPDATE SJT0BK
   SET BAED_MTH       = #{baedMth}
     , BAEJ_MTH       = #{baejMth}
     , CASH_ILBAN_RT  = #{cashIlbanRt}
     , CASH_WOOS_RT   = #{cashWoosRt}
     , STOCK_ILBAN_RT = #{stockIlbanRt}
     , STOCK_WOOS_RT  = #{stockWoosRt}
     , BROK_YMD       = TO_DATE(REPLACE(#{brokYmd}, '-', ''), 'YYYYMMDD')
     , JUCHONG_YMD    = CASE WHEN #{juchongYmd} IS NOT NULL AND #{juchongYmd} != ''
                             THEN TO_DATE(REPLACE(#{juchongYmd}, '-', ''), 'YYYYMMDD')
                             ELSE NULL
                        END
     , ILBAN_AEK      = #{ilbanAek}
     , WOOS_AEK       = #{woosAek}
 WHERE CORP_GR = #{corpGr}
   AND TR_YMD  = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
   AND TR_CD   = #{trCd}
   AND BALH_CO = #{balhCo}

mapper.delete:
